components.css:
.ds-window { background: var(--panel); border: 1px solid var(--line-strong); border-radius: var(--radius, 14px); box-shadow: 0 28px 70px -30px rgb(0 0 0 / 0.65), 0 2px 8px -4px rgb(0 0 0 / 0.35); overflow: hidden; font-family: var(--font-sans, sans-serif); color: var(--ink); }
.ds-window__bar { display: flex; align-items: center; gap: 0.6rem; height: 2.35rem; padding-inline: 0.35rem 0.5rem; border-bottom: 1px solid var(--line); background: var(--panel-2); }
.ds-window__icon { width: 1.35rem; height: 1.35rem; border-radius: 6px; background: color-mix(in oklab, var(--ink) 8%, transparent); }
.ds-window__title { font-size: 0.76rem; font-weight: 500; letter-spacing: -0.005em; }
.ds-window__sub { font-family: var(--font-mono, monospace); font-size: 0.6rem; color: var(--muted); }
.ds-controls { margin-left: auto; display: flex; gap: 0.15rem; }
.ds-controls i { width: 1.5rem; height: 1.5rem; border-radius: 6px; background: color-mix(in oklab, var(--ink) 9%, transparent); }
.ds-controls .ds-control-close:hover { background: #c65b52; }
.ds-window__body { padding: 1.15rem 1.35rem; font-size: 0.84rem; line-height: 1.55; }

.ds-dock { display: inline-flex; gap: 0.25rem; padding: 0.4rem; border: 1px solid var(--line-strong); border-radius: 18px; background: color-mix(in oklab, var(--panel) 62%, transparent); backdrop-filter: blur(22px) saturate(140%); box-shadow: 0 26px 60px -28px rgb(0 0 0 / 0.75), inset 0 1px 0 0 rgb(255 255 255 / 0.06); }
.ds-dock__item { position: relative; display: flex; width: 3.1rem; flex-direction: column; align-items: center; gap: 0.2rem; padding: 0.4rem 0.15rem 0.25rem; border: 0; border-radius: 12px; background: transparent; color: var(--muted); cursor: pointer; transition: background-color 180ms cubic-bezier(0.22, 1, 0.36, 1), translate 180ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-dock__item:hover { background: color-mix(in oklab, var(--ink) 8%, transparent); color: var(--ink); translate: 0 -3px; }
.ds-dock__item[data-open] { background: color-mix(in oklab, var(--accent) 12%, transparent); color: var(--accent); }
.ds-dock__tile { width: 20px; height: 20px; border-radius: 6px; border: 1px solid var(--line-strong); background: linear-gradient(to bottom, color-mix(in oklab, var(--panel-2) 88%, var(--accent)), var(--panel)); }
.ds-dock__dot { width: 4px; height: 4px; border-radius: 50%; background: currentColor; opacity: 0; }
.ds-dock__item[data-open] .ds-dock__dot { opacity: 0.9; box-shadow: 0 0 6px 0 color-mix(in oklab, currentColor 60%, transparent); }
.ds-dock__label { position: absolute; bottom: calc(100% + 0.5rem); left: 50%; translate: -50% 0; padding: 0.2rem 0.45rem; border: 1px solid var(--line-strong); border-radius: 6px; background: var(--panel); color: var(--ink); font-family: var(--font-mono, monospace); font-size: 0.6rem; white-space: nowrap; opacity: 0; pointer-events: none; transition: opacity 180ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-dock__item:hover .ds-dock__label { opacity: 1; }

.ds-bar { display: inline-flex; align-items: center; gap: 0.55rem; padding: 0.36rem 0.66rem; border: 1px solid var(--line); border-radius: 999px; background: color-mix(in oklab, var(--panel) 62%, transparent); backdrop-filter: blur(22px) saturate(140%); box-shadow: 0 10px 30px -20px rgb(0 0 0 / 0.55); font-family: var(--font-mono, monospace); font-size: 0.62rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); }
.ds-bar__brand { display: flex; align-items: center; gap: 0.45rem; color: var(--ink); }
.ds-bar__mark { width: 15px; height: 15px; border-radius: 50%; background: var(--ink); }
.ds-bar__brand b { font-family: var(--font-sans, sans-serif); font-size: 0.78rem; font-weight: 500; letter-spacing: 0.02em; text-transform: none; }
.ds-bar__ver { color: var(--muted); text-transform: none; }
.ds-bar__split { width: 1px; height: 0.95rem; background: var(--line-strong); }
.ds-bar__status { display: flex; align-items: center; gap: 0.38rem; color: var(--signal); }
.ds-bar__dot { width: 6px; height: 6px; border-radius: 50%; background: var(--signal); box-shadow: 0 0 8px 0 color-mix(in oklab, var(--signal) 55%, transparent); }
.ds-bar__key { padding: 0.18rem 0.42rem; border: 1px solid var(--line-strong); border-radius: 6px; background: transparent; color: var(--muted); font: inherit; cursor: pointer; transition: background-color 180ms cubic-bezier(0.22, 1, 0.36, 1), color 180ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-bar__key:hover { background: color-mix(in oklab, var(--ink) 7%, transparent); color: var(--ink); }

.ds-tile-row { display: flex; gap: 12px; }
.ds-tile { position: relative; display: grid; place-items: center; width: 44px; height: 44px; overflow: hidden; border: 1px solid var(--line-strong); border-radius: 12px; background: linear-gradient(to bottom, color-mix(in oklab, var(--panel-2) 88%, var(--tile-accent)), var(--panel)); box-shadow: inset 0 1px 0 0 rgb(255 255 255 / 0.05); color: var(--tile-accent); }
.ds-tile--letter { font-family: var(--font-sans, sans-serif); font-size: 52%; font-weight: 500; letter-spacing: -0.02em; }
.ds-tile__bar { position: absolute; inset-inline: 18%; bottom: 12%; height: 2px; border-radius: 2px; background: var(--tile-accent); opacity: 0.85; }

.ds-btn { display: inline-flex; align-items: center; gap: 0.4rem; padding: 0.45rem 0.8rem; border: 1px solid var(--line-strong); border-radius: 8px; background: transparent; color: var(--ink); font-family: var(--font-sans, sans-serif); font-size: 0.78rem; cursor: pointer; transition: background-color 180ms cubic-bezier(0.22, 1, 0.36, 1), border-color 180ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-btn:hover { background: color-mix(in oklab, var(--ink) 7%, transparent); border-color: var(--accent); }
.ds-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.ds-btn--primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); font-weight: 500; }
.ds-btn--primary:hover { background: color-mix(in oklab, var(--accent) 85%, var(--ink)); }

.ds-link-row { display: flex; align-items: center; gap: 0.5rem; border: 1px solid var(--line); border-radius: 10px; padding: 0.55rem 0.75rem; font-family: var(--font-sans, sans-serif); font-size: 0.8rem; text-decoration: none; color: var(--ink); transition: border-color 180ms cubic-bezier(0.22, 1, 0.36, 1); }
.ds-link-row:hover { border-color: var(--accent); }
.ds-link-row .ds-label { flex: none; }
